 List<IMyShipConnector> connectors = new List<IMyShipConnector>(); List<IMyLightingBlock> statusLights = new List<IMyLightingBlock>(); List<IMyTextPanel> statusLCDs = new List<IMyTextPanel>(); List<IMyTextPanel> logLCDs = new List<IMyTextPanel>(); List<IMyDoor> doors = new List<IMyDoor>(); IMySoundBlock speakerReady, speakerLocked, speakerUnlinked; string connectorGroupName = "Docking Connectors"; string lightGroupName = "Docking Lights"; string lcdGroupName = "Docking LCDs"; string lcdLogGroupName = "Docking Logs"; string doorGroupName = "Docking Doors"; string speakerReadyName = "Speaker Ready"; string speakerLockedName = "Speaker Locked"; string speakerUnlinkedName = "Speaker Unlinked"; float blinkInterval = 1.0f; float blinkLength = 50f; Color colorConnected = Color.Green; Color colorConnectable = Color.Yellow; Color colorUnconnected = Color.Red; Color textColor = Color.White; bool autoConnect = false; bool autoDoors = false; bool useLog = false; MyShipConnectorStatus lastStatus = MyShipConnectorStatus.Unconnected; string errorMessage = ""; public Program() { EnsureDefaultCustomData(); LoadSettings(); Runtime.UpdateFrequency = UpdateFrequency.Update100; GridTerminalSystem.GetBlockGroupWithName(connectorGroupName)?.GetBlocksOfType(connectors); GridTerminalSystem.GetBlockGroupWithName(lightGroupName)?.GetBlocksOfType(statusLights); GridTerminalSystem.GetBlockGroupWithName(lcdGroupName)?.GetBlocksOfType(statusLCDs); GridTerminalSystem.GetBlockGroupWithName(lcdLogGroupName)?.GetBlocksOfType(logLCDs); GridTerminalSystem.GetBlockGroupWithName(doorGroupName)?.GetBlocksOfType(doors); speakerReady = GridTerminalSystem.GetBlockWithName(speakerReadyName) as IMySoundBlock; speakerLocked = GridTerminalSystem.GetBlockWithName(speakerLockedName) as IMySoundBlock; speakerUnlinked = GridTerminalSystem.GetBlockWithName(speakerUnlinkedName) as IMySoundBlock; ValidateConfiguration(); } public void Main(string argument, UpdateType updateSource) { if (!string.IsNullOrWhiteSpace(errorMessage)) { Echo("[FEHLER]\n" + errorMessage); return; } var currentStatus = GetHighestConnectorStatus(); if (currentStatus != lastStatus) { PlayStatusSound(currentStatus); UpdateLights(currentStatus); UpdateLCDs(currentStatus); if (useLog) WriteLog(currentStatus); if (autoDoors) ToggleDoors(currentStatus); lastStatus = currentStatus; } if (autoConnect && currentStatus == MyShipConnectorStatus.Connectable) foreach (var con in connectors) con.Connect(); } MyShipConnectorStatus GetHighestConnectorStatus() { MyShipConnectorStatus result = MyShipConnectorStatus.Unconnected; foreach (var c in connectors) { if (c.Status == MyShipConnectorStatus.Connected) return MyShipConnectorStatus.Connected; else if (c.Status == MyShipConnectorStatus.Connectable) result = MyShipConnectorStatus.Connectable; } return result; } void PlayStatusSound(MyShipConnectorStatus status) { StopAllSounds(); if (status == MyShipConnectorStatus.Connected && speakerLocked != null) speakerLocked.Play(); else if (status == MyShipConnectorStatus.Connectable && speakerReady != null) speakerReady.Play(); else if (speakerUnlinked != null) speakerUnlinked.Play(); } void StopAllSounds() { speakerReady?.Stop(); speakerLocked?.Stop(); speakerUnlinked?.Stop(); } void UpdateLights(MyShipConnectorStatus status) { Color target = colorUnconnected; bool shouldBlink = false; if (status == MyShipConnectorStatus.Connected) { target = colorConnected; shouldBlink = false; } else if (status == MyShipConnectorStatus.Connectable) { target = colorConnectable; shouldBlink = true; } else { target = colorUnconnected; shouldBlink = false; } foreach (var l in statusLights) { l.Enabled = true; l.Color = target; if (shouldBlink) { l.BlinkIntervalSeconds = blinkInterval; l.BlinkLength = blinkLength; } else { l.BlinkIntervalSeconds = 0f; l.BlinkLength = 0f; } } } void UpdateLCDs(MyShipConnectorStatus status) { string ownConnectorName = connectors.Count > 0 ? connectors[0].CustomName : "Kein Connector"; string text = $"Connector Status:\n{status}\n{ownConnectorName}"; if (status == MyShipConnectorStatus.Connected) { foreach (var c in connectors) { if (c.Status == MyShipConnectorStatus.Connected && c.OtherConnector != null) { text += $"\nVerbunden mit:\n{c.OtherConnector.CustomName}"; break; } } } foreach (var lcd in statusLCDs) { lcd.ContentType = ContentType.TEXT_AND_IMAGE; lcd.WriteText(text); } } void WriteLog(MyShipConnectorStatus status) { string statusStr = (int)status == -1 ? "OFFLINE" : status.ToString(); string connectorInfo = ""; if (status == MyShipConnectorStatus.Connected) { foreach (var c in connectors) { if (c.Status == MyShipConnectorStatus.Connected && c.OtherConnector != null) { connectorInfo = $"-> Verbunden mit: {c.OtherConnector.CustomName}"; break; } } } string logEntry = $"[{DateTime.Now:HH:mm:ss}] {statusStr}"; if (!string.IsNullOrEmpty(connectorInfo)) logEntry += $"\n{connectorInfo}"; const int maxLogLines = 60; foreach (var lcd in logLCDs) { lcd.ContentType = ContentType.TEXT_AND_IMAGE; var oldText = lcd.GetText(); var lines = oldText.Split('\n').ToList(); lines.Insert(0, logEntry); while (lines.Count > maxLogLines) lines.RemoveAt(lines.Count - 1); lcd.WriteText(string.Join("\n", lines)); } } void ToggleDoors(MyShipConnectorStatus status) { foreach (var door in doors) { if (status == MyShipConnectorStatus.Connected) door.OpenDoor(); else door.CloseDoor(); } } void LoadSettings() { if (string.IsNullOrWhiteSpace(Me.CustomData)) return; var lines = Me.CustomData.Split('\n'); string section = ""; foreach (var rawLine in lines) { string line = rawLine.Trim(); if (string.IsNullOrWhiteSpace(line)) continue; if (line.StartsWith("[") && line.EndsWith("]")) { section = line.Substring(1, line.Length - 2); continue; } var parts = line.Split('='); if (parts.Length != 2) continue; string key = parts[0].Trim(); string val = parts[1].Trim(); switch (section) { case "Groups": if (key == "Connectors") connectorGroupName = val; if (key == "Lights") lightGroupName = val; if (key == "LCDs") lcdGroupName = val; if (key == "LogLCDs") lcdLogGroupName = val; if (key == "Doors") doorGroupName = val; break; case "Flags": if (key == "AutoConnect") autoConnect = val.ToLower() == "true"; if (key == "AutoDoors") autoDoors = val.ToLower() == "true"; if (key == "EnableLog") useLog = val.ToLower() == "true"; break; case "Speakers": if (key == "Ready") speakerReadyName = val; if (key == "Locked") speakerLockedName = val; if (key == "Unlinked") speakerUnlinkedName = val; break; case "Lights": if (key == "ConnectedColor") colorConnected = ParseColor(val); if (key == "ConnectableColor") colorConnectable = ParseColor(val); if (key == "UnconnectedColor") colorUnconnected = ParseColor(val); if (key == "BlinkInterval") float.TryParse(val, out blinkInterval); if (key == "BlinkLength") float.TryParse(val, out blinkLength); break; case "Text": if (key == "TextColor") textColor = ParseColor(val); break; } } } Color ParseColor(string val) { try { var parts = val.Split(','); if (parts.Length != 3) return Color.White; return new Color( int.Parse(parts[0]), int.Parse(parts[1]), int.Parse(parts[2]) ); } catch { return Color.White; } } void EnsureDefaultCustomData() { if (!string.IsNullOrWhiteSpace(Me.CustomData)) return; Me.CustomData = "[Groups]\n" + "Connectors=Docking Connectors\n" + "Lights=Docking Lights\n" + "LCDs=Docking LCDs\n" + "LogLCDs=Docking Logs\n" + "Doors=Docking Doors\n\n" + "[Flags]\n" + "AutoConnect=false\n" + "AutoDoors=false\n" + "EnableLog=false\n\n" + "[Speakers]\n" + "Ready=Speaker Ready\n" + "Locked=Speaker Locked\n" + "Unlinked=Speaker Unlinked\n\n" + "[Lights]\n" + "ConnectedColor=0,255,0\n" + "ConnectableColor=255,255,0\n" + "UnconnectedColor=255,0,0\n" + "BlinkInterval=1.0\n" + "BlinkLength=50\n\n" + "[Text]\n" + "TextColor=255,255,255\n"; } void ValidateConfiguration() { var errors = new List<string>(); if (connectors.Count == 0) errors.Add("Keine Connector-Gruppe gefunden: " + connectorGroupName); if (statusLCDs.Count == 0) errors.Add("Keine LCD-Gruppe gefunden: " + lcdGroupName); if (statusLights.Count == 0) errors.Add("Keine Licht-Gruppe gefunden: " + lightGroupName); if (speakerReady == null) errors.Add("Lautsprecher (Ready) nicht gefunden: " + speakerReadyName); if (speakerLocked == null) errors.Add("Lautsprecher (Locked) nicht gefunden: " + speakerLockedName); if (speakerUnlinked == null) errors.Add("Lautsprecher (Unlinked) nicht gefunden: " + speakerUnlinkedName); errorMessage = string.Join("\n", errors); } 